#if TEST_BUILD
using System;using System.IO;using System.Drawing;using System.Threading.Tasks;using System.Diagnostics;
internal sealed partial class ControlWindow {
 async Task WaitOfflineState(string target){var t=Stopwatch.StartNew();while(State!=target){if(t.Elapsed.TotalSeconds>15)throw new Exception("Expected "+target+", got "+State);await Task.Delay(100);}}
 void OfflineShot(string name){using(var b=new Bitmap(ClientSize.Width,ClientSize.Height)){DrawToBitmap(b,new Rectangle(Point.Empty,ClientSize));b.Save(Path.Combine(Common.Root,"evidence",name+".png"));}Common.ReplaceJson(Path.Combine(Common.Root,"evidence",name+".json"),new{state=State,selected=selected.Name,actual=activeRunName,scale=uiScale,client=ClientSize.ToString(),stopText=stop.Text,confirmVisible=confirmPreview.Visible,muted=settings.Muted,volume=settings.Volume,run=CurrentRun});}
 internal async Task RunOfflineCheck(){try{SelectWallpaper(library.Doc.Items.Find(x=>x.Id=="builtin-317495"));OfflineShot("initial");await StartMode("preview");await WaitOfflineState("preview");await Task.Delay(2200);OfflineShot("preview-ui");Common.ReplaceJson(Path.Combine(Common.Root,"evidence/capture-preview.json"),new{run=CurrentRun});await Task.Delay(3500);await StopManaged("offline-preview-stop");if(!Clean)throw new Exception("Preview cleanup unconfirmed");await StartMode("desktop");await WaitOfflineState("mounted");await Task.Delay(2200);SelectWallpaper(library.Doc.Items.Find(x=>x.Id!="builtin-317495"));await Task.Delay(600);OfflineShot("desktop-ui");Common.ReplaceJson(Path.Combine(Common.Root,"evidence/capture-desktop.json"),new{run=CurrentRun});await Task.Delay(3500);if(PlayerRole!="alive"||activeRunName==selected.Name)throw new Exception("Selection/playback mismatch");Write("offline-test-passed",new{preview=true,desktop=true,selectionSeparate=true,normalPlaybackDeadline=false});Close();return;}catch(Exception ex){Write("offline-test-failed",new{error=ex.ToString()});}await StopManaged("offline-test-failure");Close();}
}
#endif
